function ParseJSON(msg) {
    if (typeof msg.payload === 'string') {
        try {
            msg.payload = JSON.parse(msg.payload);
            msg.parsedSuccessfully = true;
        } catch (e) {
            msg.payload = { error: "Failed to parse JSON", originalPayload: msg.payload };
            msg.parsedSuccessfully = false;
            return null;
        }
    } else {
        // If it's already an object, no need to parse
        msg.parsedSuccessfully = true;
    }
    if (msg.payload.error == "Invalid JSON"){
        return null;
    }
    return msg;
}

