const previousJobName = context.get('lastPublishedJobName');

// Do not continuously publish the same job (or the same cleared state) on every poll.
if (previousJobName === nextJobName) return null;

// An in-progress message without a job name must not accidentally clear the database.
if (!shouldClear && !jobName) return null;

context.set('lastPublishedJobName', nextJobName);
if (shouldClear) {
    global.set('current_job_name', '');
    delete msg.jobName;
}

return {
    topic: 'fleet/' + tenantId + '/' + robotId + '/job_update',
    payload: JSON.stringify({ job_name: nextJobName })
};

if (msg.topic !== 'wait/start' && msg.topic !== 'wait/done' && msg.topic !== 'wait/cancelled') return null;

var fs = global.get('fs');
var path = '/home/amb/.node-red/uibuilder/AMB-ROBOT-V2/src/wait-status.json';
var state = msg.topic === 'wait/start'
    ? { active: true, payload: msg.payload }
    : { active: false };

try { fs.writeFileSync(path, JSON.stringify(state, null, 2)); }
catch (e) { node.warn('wait-status.json write failed: ' + e.message); }

return null;

var poi = msg.poi || '';
var occupiedBy = (msg.payload && msg.payload.occupied_by) || null;

if (msg.payload && msg.payload.available === true) {
    var availableUi = {
        topic: 'poi/available',
        payload: { poi: poi, available: true }
    };
    return [msg, null, availableUi];
}

node.warn('POI ' + poi + ' occupied by ' + (occupiedBy || '?') + '  retrying');
var waitingUi = {
    topic: 'poi/waiting',
    payload: {
        poi: poi,
        available: false,
        occupied_by: occupiedBy,
        retry_seconds: 5
    }
};
return [null, msg, waitingUi];

// Outputs: legacy command, browser reply, Fleet progress query.
const p = msg.payload || {};
if (['sound','relocate','do_control'].includes(msg.topic)) msg._maintenanceRequestId=p.request_id;
const reply = (topic, payload) => ({ topic, payload, _socketId:msg._socketId });
if (msg.topic === 'ui/state/request') {
    const cache = flow.get('site_ui_cache') || {};
    const messages = Object.values(cache).map(item => ({ ...item, _socketId:msg._socketId, _replay:true }));
    messages.push(reply('ui/runtime/restored', { at:Date.now() }));
    return [{ topic:'config/request', payload:{} }, messages, { payload:{} }];
}
if (msg.topic === 'ui/settings/request' || msg.topic === 'ui/settings/save') return null;
let topic = msg.topic;
let payload = p;
if (topic === 'edge/command/request') {
    const params = p.params || {};
    topic = ({ navigate:'nav', pause:'pause', resume:'resume', cancel:'cancel', charge:'charge' })[p.action];
    if (!topic) return [null, reply('ui/command/ack', { request_id:p.request_id, accepted:false, error:'Unsupported action' }), null];
    payload = { ...params, point:params.target, chargeId:params.target, request_id:p.request_id };
    msg._uiRequestId = p.request_id;
    msg._uiAction = topic;
}
if (topic === 'fleet/command/request') {
    if (p.action === 'sync') return [{topic:'config/request',payload:{}}, null, {payload:{}}];
    topic = ({ start:'getjob', cancel:'cancel' })[p.action];
    if (!topic) return null;
    payload = { request_id:p.command_id };
}
const commands = new Set(['nav','pause','resume','cancel','charge','getjob','enqueue','wait/control/ready','wait/control/cancel']);
if (commands.has(topic)) {
    const id = p.request_id || p.command_id;
    if (!id) return [null, reply('ui/command/ack', {accepted:false,error:'Request ID required'}), null];
    const seen = flow.get('site_ui_commands') || {};
    const now = Date.now();
    for (const key of Object.keys(seen)) if (now - seen[key] > 600000) delete seen[key];
    if (seen[id]) return [null, reply('ui/command/ack', {request_id:id,accepted:true,duplicate:true}), null];
    seen[id] = now;
    flow.set('site_ui_commands', seen);
}
return [{ ...msg, topic, payload }, null, null];

// Cache only resumable UI state, not commands or command acknowledgements.
const cache = flow.get('site_ui_cache') || {};
const topic = msg.topic;
if ((topic === 'wait/done' || topic === 'wait/cancelled') && (!msg.payload?.waitId || msg.payload.waitId === cache['wait/start']?.payload?.waitId)) delete cache['wait/start'];
if (topic === 'poi/available' || topic === 'poi/cancelled') delete cache['poi/waiting'];
if (['enqueue/success','nav/started','wait/start','wait/done','wait/cancelled','nav/cancelled','poi/cancelled'].includes(topic)) delete cache['ui/page'];
if (['nav/arrived','nav/cancelled','nav/error','wait/start'].includes(topic)) {delete cache['nav/progress'];delete cache['destination'];}
const allowed = ['battery','poi','status','robot/runtime','robotName','wifi','robot/error','error/status','alarm/status','estop','estop/status','config/pages','config/robot','config/conn','fleet/job-progress','ui/page','wait/start','poi/waiting','nav/progress','destination'];
if (allowed.includes(topic)) cache[topic] = { topic, payload:msg.payload, _observedAt:Date.now() };
flow.set('site_ui_cache', cache);
return { ...msg, _observedAt:Date.now() };

// Node-RED Function body; global.fs must be configured in settings.js.
const topic = msg.topic;
if (!['ui/settings/request', 'ui/settings/save'].includes(topic)) return null;
const p = msg.payload || {};
function reply(topic, payload) { return { topic, payload, _socketId:msg._socketId }; }
try {
    const fs = global.get('fs');
    if (!fs) throw new Error('Persistent settings unavailable: configure functionGlobalContext.fs');
    const file = env.get('SVI_UI_CONFIG_PATH') || (env.get('HOME') + '/.node-red/svi-ui-settings.json');
    const cfg = global.get('cfg') || {};
    let saved = { revision:0, config:{ standbyPoint:cfg.standbyPoi || null, chargingPoint:cfg.chargePoi || null, visiblePoints:[] } };
    try { saved = JSON.parse(fs.readFileSync(file, 'utf8')); }
    catch (e) { if (e.code !== 'ENOENT') throw e; }
    if (!saved.config || !Number.isInteger(saved.revision)) throw new Error('Invalid settings file; repair before saving');
    if (topic === 'ui/settings/save') {
        if (p.revision !== saved.revision) throw new Error('Settings changed in another session. Reload before saving.');
        const catalog = flow.get('v2_point_catalog');
        if (p.section !== 'fleet' && (!catalog || Date.now() - catalog.at > 300000)) throw new Error('Refresh the point catalog before saving');
        const ids = new Set((catalog?.points || []).map(point => point.id));
        const values = p.values || {};
        if (p.section === 'fleet') {
            const pages = global.get('fleet_getjob_pages');
            if (!Array.isArray(pages)) throw new Error('Load Fleet configuration before saving');
            const keys = new Set(pages.map(page => page.sourceProjectId ? 'project:' + page.sourceProjectId + ':page:' + page.id : 'page:' + page.id));
            if (!Array.isArray(values.pages) || values.pages.some(key => !keys.has(key))) throw new Error('Invalid Fleet page selection');
            saved.config.fleetPages = [...new Set(values.pages)];
        } else if (p.section === 'points') {
            if (!Array.isArray(values.points)) throw new Error('Invalid point selection');
            const selected = values.points.map(point => ({ id:String(point.id), label:String(point.label || point.id).trim() }));
            if (selected.some(point => !ids.has(point.id)) || new Set(selected.map(point => point.id)).size !== selected.length) throw new Error('Selection contains invalid or duplicate points');
            saved.config.visiblePoints = selected;
        } else if (p.section === 'standby' || p.section === 'charge') {
            const point = p.section === 'standby' ? values.standbyPoint : values.chargePoint;
            if (!ids.has(point)) throw new Error('Point is not in the current map');
            saved.config[p.section === 'standby' ? 'standbyPoint' : 'chargingPoint'] = point;
            saved.config[p.section === 'standby' ? 'standbyLabel' : 'chargingLabel'] = String(values.label || point);
        } else throw new Error('Unsupported settings section');
        saved.revision++;
        saved.config.savedAt = new Date().toISOString();
        fs.writeFileSync(file + '.tmp', JSON.stringify(saved, null, 2), 'utf8');
        fs.renameSync(file + '.tmp', file);
    }
    global.set('v2_saved_config', saved.config);
    global.set('cfg', Object.assign({}, cfg, { standbyPoi:saved.config.standbyPoint, chargePoi:saved.config.chargingPoint }));
    return reply(topic === 'ui/settings/save' ? 'ui/settings/saved' : 'ui/settings/state', { ...saved, request_id:p.request_id });
} catch (error) { return reply('ui/settings/error', { request_id:p.request_id, error:error.message }); }

// Publish the complete SEER task state. This is the authoritative UI movement
// signal and remains active even when no robot-nav node owns the command.
const p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const taskStatus = Number(p.task_status);
const runningStatus = Number(p.running_status);
const cachedProgress = (flow.get('site_ui_cache') || {})['nav/progress'];
// robot-nav deliberately reports "waiting" during SEER's short NONE grace
// period after an accepted navigate command. Do not overwrite that newer,
// command-correlated observation with a generic idle poll.
if (taskStatus === 0 && cachedProgress && Date.now() - Number(cachedProgress._observedAt || 0) < 10000) return null;
let mode = String(p.mode || '').toLowerCase();
if (taskStatus === 3 || p.is_suspended === true) mode = 'suspended';
else if (taskStatus === 2 || runningStatus === 1 || p.is_running === true) mode = 'running';
else if (taskStatus === 1 || p.is_waiting === true) mode = 'waiting';
else if (taskStatus === 4) mode = 'completed';
else mode = 'idle';

return {
    topic: 'robot/runtime',
    payload: {
        mode,
        task_status: Number.isFinite(taskStatus) ? taskStatus : null,
        running_status: Number.isFinite(runningStatus) ? runningStatus : null,
        is_running: mode === 'running' || mode === 'waiting',
        is_suspended: mode === 'suspended',
        is_idle: mode === 'idle',
        target_point: p.target_point || null,
        current_station: p.current_station || p.current_poi || null,
        unfinished_path: Array.isArray(p.unfinished_path) ? p.unfinished_path : [],
        observed_at: Date.now()
    }
};

// Gateway HTTP success means accepted, not physically paused/resumed. Output 2
// immediately re-queries SEER so robot/runtime can provide confirmation.
const response = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const accepted = response.accepted !== false;
return [
    {
        topic: 'ui/control/accepted',
        payload: {
            request_id: msg._uiRequestId || null,
            action: msg._uiAction || msg.topic || 'control',
            accepted,
            command_id: response.command_id || msg.commandId || null,
            message: response.message || (accepted ? 'Gateway accepted the request' : 'Gateway rejected the request')
        },
        _socketId: msg._socketId
    },
    accepted ? { topic: 'runtime/verify', payload: {}, _uiAction: msg._uiAction } : null
];
